/**
 * ReturnDistribution
 *
 * A single histogram bucket for the PnL return distribution.
 *
 * Attributes:
 * bucket_min: Inclusive lower bound of this PnL bucket.
 * bucket_max: Exclusive upper bound of this PnL bucket
 * (the last bucket is inclusive on both ends).
 * count: Number of trades whose PnL falls within this bucket.
 * frequency: Fraction of total trades in this bucket (0.0–1.0).
 */
export type ReturnDistribution = {
    /**
     * Bucket Min
     *
     * Inclusive lower bound of this PnL histogram bucket in account currency.
     */
    bucket_min: string;
    /**
     * Bucket Max
     *
     * Exclusive upper bound of this PnL histogram bucket in account currency. The final bucket is inclusive on the upper bound.
     */
    bucket_max: string;
    /**
     * Count
     *
     * Number of closed trades whose PnL falls within this bucket.
     */
    count: number;
    /**
     * Frequency
     *
     * Fraction of total closed trades that fall within this bucket (0.0–1.0). Sum of all bucket frequencies equals 1.0 when trades exist.
     */
    frequency: string;
};

/**
 * RollingWinratePoint
 *
 * A single data point in the rolling win-rate series.
 *
 * Each point represents the win rate computed over the ``window`` most
 * recent closed trades up to and including the trade at ``trade_index``.
 *
 * Attributes:
 * trade_index: Zero-based index of the trade in the chronological series.
 * closed_at: UTC timestamp when the trade was closed.
 * rolling_winrate: Win rate (fraction of wins) over the sliding window
 * ending at this trade (0.0–1.0).
 * window: The window size used for this computation.
 */
export type RollingWinratePoint = {
    /**
     * Trade Index
     *
     * Zero-based ordinal position of the trade in the chronological closed-trade series.
     */
    trade_index: number;
    /**
     * Closed At
     *
     * UTC timestamp when the trade at this index was closed.
     */
    closed_at: string;
    /**
     * Rolling Winrate
     *
     * Fraction of winning trades (PnL > 0) over the ``window`` most recent trades ending at this index (0.0–1.0).
     */
    rolling_winrate: string;
    /**
     * Window
     *
     * Number of trades in the sliding window used for this point.
     */
    window: number;
};

