/**
 * TaxAnnualSummary
 *
 * Annual tax summary for German Anlage KAP reporting.
 *
 * Splits realised P&L in EUR into two §20 EStG categories:
 *
 * - **equities**: §20 Abs. 2 Nr. 1 EStG — ``AssetClass.EQUITY`` trades.
 * - **derivatives**: §20 Abs. 2 Nr. 3 EStG — all other asset classes
 * (``OPTION``, ``FUTURE``, ``FOREX``, ``CRYPTO``).
 *
 * Attributes:
 * year: Calendar year this summary covers.
 * equities: P&L block for equity (stock) trades.
 * derivatives: P&L block for derivatives / other instruments.
 * total_net_eur: Combined net P&L across both categories.
 * trades_missing_eur: Number of closed trades in this year where
 * ``pnl_eur`` is NULL (could not be converted to EUR).
 * dividends_eur: Total dividends in EUR across all accounts.
 * withholding_tax_eur: Total withholding tax in EUR across all accounts.
 * interest_eur: Total interest income in EUR across all accounts.
 */
export type TaxAnnualSummary = {
    /**
     * Year
     *
     * Calendar year this summary covers.
     */
    year: number;
    /**
     * §20 Abs. 2 Nr. 1 EStG — realised gains and losses from equity trades.
     */
    equities: TaxCategoryBlock;
    /**
     * §20 Abs. 2 Nr. 3 EStG — realised gains and losses from derivatives and other instruments (options, futures, forex, crypto).
     */
    derivatives: TaxCategoryBlock;
    /**
     * Total Net Eur
     *
     * Combined net P&L in EUR across both categories.
     */
    total_net_eur: string;
    /**
     * Trades Missing Eur
     *
     * Number of closed trades in this year where pnl_eur could not be determined (exchange rate was unavailable at import time).
     */
    trades_missing_eur?: number;
    /**
     * Dividends Eur
     *
     * Total dividends received in EUR across all accounts for this year.
     */
    dividends_eur?: string;
    /**
     * Withholding Tax Eur
     *
     * Total withholding tax (Quellensteuer) paid in EUR across all accounts for this year. Always <= 0.
     */
    withholding_tax_eur?: string;
    /**
     * Interest Eur
     *
     * Total interest income in EUR across all accounts for this year.
     */
    interest_eur?: string;
    /**
     * Accounts
     *
     * Detailed tax summaries broken down by individual accounts.
     */
    accounts?: Array<AccountTaxSummary>;
};

/**
 * TaxCategoryBlock
 *
 * P&L summary for one §20 EStG tax category (equities or derivatives).
 *
 * Attributes:
 * gains_eur: Sum of all positive ``pnl_eur`` values in this category.
 * losses_eur: Sum of all negative ``pnl_eur`` values in this category
 * (always <= 0).
 * net_eur: ``gains_eur + losses_eur`` — the net result for this category.
 * trade_count: Number of closed trades with a non-null ``pnl_eur`` in
 * this category.
 */
export type TaxCategoryBlock = {
    /**
     * Gains Eur
     *
     * Total realised gains in EUR for this category (sum of positive pnl_eur). Always >= 0.
     */
    gains_eur: string;
    /**
     * Losses Eur
     *
     * Total realised losses in EUR for this category (sum of negative pnl_eur). Always <= 0.
     */
    losses_eur: string;
    /**
     * Net Eur
     *
     * Net P&L in EUR for this category (gains_eur + losses_eur).
     */
    net_eur: string;
    /**
     * Trade Count
     *
     * Number of closed trades with a known pnl_eur in this category.
     */
    trade_count: number;
};

/**
 * TokenResponse
 *
 * Response schema returned by the token and refresh endpoints.
 *
 * Attributes:
 * access_token: Signed JWT string to be sent as a Bearer token.
 * token_type: Always ``"bearer"`` per OAuth2 convention.
 */
export type TokenResponse = {
    /**
     * Access Token
     *
     * Signed JWT access token. Include in the 'Authorization: Bearer <token>' header.
     */
    access_token: string;
    /**
     * Token Type
     *
     * Token type — always 'bearer'.
     */
    token_type?: string;
};

/**
 * TradeCreateRequest
 *
 * Public API request body for creating a new trade.
 *
 * This is the schema exposed in the OpenAPI documentation and used as the
 * FastAPI request body type in route handlers.  It does **not** contain
 * ``user_id`` — that field is injected by the handler from the authenticated
 * user and merged into :class:`TradeCreate` before service calls.
 *
 * Attributes:
 * symbol: Ticker symbol (e.g. ``"AAPL"``).
 * direction: Long or short.
 * asset_class: Asset class of the instrument.
 * quantity: Number of units / contracts traded.
 * entry_price: Execution price at open.
 * exit_price: Execution price at close (omit for open trades).
 * stop_loss: Optional stop-loss price.
 * take_profit: Optional take-profit price.
 * opened_at: Timezone-aware UTC timestamp of position open.
 * closed_at: Timezone-aware UTC timestamp of position close.
 * pnl: Realised PnL.
 * commission: Total commission paid; defaults to zero.
 * notes: Free-text notes.
 * currency: ISO-4217 currency code (e.g. ``"USD"``).
 * pnl_eur: Realised P&L in EUR (optional, set by broker importers or manually).
 * account_id: Optional broker account UUID.
 * playbook_id: Optional playbook UUID.
 * tag_ids: List of tag UUIDs to attach.
 * commission: Total commission paid; defaults to zero.
 * notes: Free-text notes.
 * account_id: Optional broker account UUID.
 * playbook_id: Optional playbook UUID.
 * tag_ids: List of tag UUIDs to attach.
 */
export type TradeCreateRequest = {
    /**
     * Symbol
     *
     * Ticker symbol of the traded instrument. Maximum 30 characters (e.g. 'AAPL', 'EURUSD', 'CHTR  251003P00240000').
     */
    symbol: string;
    /**
     * Trade direction — 'LONG' for a buy position, 'SHORT' for a sell position.
     */
    direction: Direction;
    /**
     * Asset class of the traded instrument. One of: EQUITY, OPTION, FUTURE, FOREX, CRYPTO. Null for COMBO trades.
     */
    asset_class?: AssetClass | null;
    /**
     * Is Combo
     *
     * True when this trade is a multi-instrument COMBO position.
     */
    is_combo?: boolean;
    /**
     * Quantity
     *
     * Number of units, shares, or contracts traded. Must be greater than zero.
     */
    quantity?: number | string | null;
    /**
     * Entry Price
     *
     * Execution price at which the position was opened. Must be greater than zero.
     */
    entry_price?: number | string | null;
    /**
     * Exit Price
     *
     * Execution price at which the position was closed. Omit or set to null for trades that are still open.
     */
    exit_price?: number | string | null;
    /**
     * Stop Loss
     *
     * Stop-loss price level for the trade. Omit or set to null if no stop-loss was set.
     */
    stop_loss?: number | string | null;
    /**
     * Take Profit
     *
     * Take-profit price level for the trade. Omit or set to null if no take-profit was set.
     */
    take_profit?: number | string | null;
    /**
     * Opened At
     *
     * Timezone-aware UTC timestamp of when the position was opened. Naive datetimes (without timezone info) are rejected.
     */
    opened_at: string;
    /**
     * Closed At
     *
     * Timezone-aware UTC timestamp of when the position was closed. Omit or set to null for trades that are still open. Naive datetimes are rejected.
     */
    closed_at?: string | null;
    /**
     * Pnl
     *
     * Realised profit or loss for this trade in account currency. Can be supplied manually; automated computation is planned for a later iteration. Null for open trades.
     */
    pnl?: number | string | null;
    /**
     * Net Pnl
     *
     * Realised net profit or loss for this trade in account currency. Null for open trades.
     */
    net_pnl?: number | string | null;
    /**
     * Commission
     *
     * Total commission paid for this trade. Defaults to zero.
     */
    commission?: number | string;
    /**
     * Notes
     *
     * Free-text notes attached to this trade, e.g. trade rationale, emotional state, or post-trade review.
     */
    notes?: string | null;
    /**
     * User Rating
     *
     * Optional user rating for this trade on a 1-5 scale.
     */
    user_rating?: number | null;
    /**
     * Tradingview Link
     *
     * Optional link to a TradingView chart for this trade.
     */
    tradingview_link?: string | null;
    /**
     * Screenshots
     *
     * List of screenshot URLs for this trade.
     */
    screenshots?: Array<string> | null;
    /**
     * Currency
     *
     * ISO-4217 currency code of the trade (e.g. 'USD'). Set automatically by broker importers; can also be set manually.
     */
    currency?: string | null;
    /**
     * Pnl Eur
     *
     * Realised P&L converted to EUR. Set automatically by broker importers at the official Bundesbank daily rate; can also be set manually.
     */
    pnl_eur?: number | string | null;
    /**
     * Net Pnl Eur
     *
     * Realised net P&L converted to EUR. Set automatically by broker importers at the official Bundesbank daily rate; can also be set manually.
     */
    net_pnl_eur?: number | string | null;
    /**
     * Account Id
     *
     * UUID of the broker account this trade belongs to. Omit to create an unassigned trade.
     */
    account_id?: string | null;
    /**
     * Playbook Id
     *
     * UUID of the playbook (strategy) to associate with this trade. Omit or set to null for no playbook.
     */
    playbook_id?: string | null;
    /**
     * Tag Ids
     *
     * List of tag UUIDs to attach to this trade. All UUIDs must belong to the authenticated user.
     */
    tag_ids?: Array<string>;
    /**
     * Executions
     *
     * Optional list of manual execution legs to create with the trade.
     */
    executions?: Array<LogicalExecutionCreate> | null;
};

/**
 * TradeMetrics
 *
 * Aggregate performance metrics computed from a set of closed trades.
 *
 * Attributes:
 * total_trades: Total number of closed trades with a PnL value.
 * winning_trades: Number of trades with PnL > 0.
 * losing_trades: Number of trades with PnL < 0.
 * breakeven_trades: Number of trades with PnL == 0.
 * win_rate: Fraction of winning trades over total (0.0–1.0).
 * loss_rate: Fraction of losing trades over total (0.0–1.0).
 * avg_win: Average PnL of winning trades.
 * avg_loss: Average PnL of losing trades (negative value).
 * profit_factor: Gross profit divided by the absolute gross loss.
 * ``None`` when there are no losing trades.
 * expectancy: Expected PnL per trade:
 * ``win_rate * avg_win + loss_rate * avg_loss``.
 * total_pnl: Sum of PnL across all closed trades.
 * gross_profit: Sum of PnL for winning trades only (positive).
 * gross_loss: Sum of PnL for losing trades only (negative).
 * max_consecutive_wins: Longest winning streak.
 * max_consecutive_losses: Longest losing streak.
 * avg_trade_duration_seconds: Mean duration between ``opened_at`` and
 * ``closed_at`` in seconds. ``None`` if no trade has both timestamps.
 * sharpe_ratio: Annualised Sharpe ratio (risk-free rate = 0), using
 * daily PnL grouped by ``closed_at`` date. ``None`` if fewer than
 * 2 closed trades exist.
 */
export type TradeMetrics = {
    /**
     * Total Trades
     *
     * Total number of closed trades included in this computation.
     */
    total_trades: number;
    /**
     * Winning Trades
     *
     * Number of trades with a positive PnL.
     */
    winning_trades: number;
    /**
     * Losing Trades
     *
     * Number of trades with a negative PnL.
     */
    losing_trades: number;
    /**
     * Breakeven Trades
     *
     * Number of trades with a PnL of exactly zero.
     */
    breakeven_trades: number;
    /**
     * Win Rate
     *
     * Fraction of winning trades over the total number of trades (0.0–1.0). A value of 0.667 means 66.7 % of trades were winners.
     */
    win_rate: string;
    /**
     * Loss Rate
     *
     * Fraction of losing trades over the total number of trades (0.0–1.0). Complements win_rate.
     */
    loss_rate: string;
    /**
     * Avg Win
     *
     * Average PnL of winning trades in account currency.
     */
    avg_win: string;
    /**
     * Avg Loss
     *
     * Average PnL of losing trades in account currency (negative value).
     */
    avg_loss: string;
    /**
     * Profit Factor
     *
     * Gross profit divided by the absolute value of gross loss. A profit factor above 1.0 means the strategy is profitable overall. Null when there are no losing trades.
     */
    profit_factor: string | null;
    /**
     * Expectancy
     *
     * Expected PnL per trade: win_rate × avg_win + loss_rate × avg_loss. Positive expectancy means the strategy is profitable on average.
     */
    expectancy: string;
    /**
     * Total Pnl
     *
     * Sum of PnL across all closed trades in account currency.
     */
    total_pnl: string;
    /**
     * Gross Profit
     *
     * Sum of PnL for winning trades only (always >= 0).
     */
    gross_profit: string;
    /**
     * Gross Loss
     *
     * Sum of PnL for losing trades only (always <= 0).
     */
    gross_loss: string;
    /**
     * Max Consecutive Wins
     *
     * Length of the longest consecutive winning streak.
     */
    max_consecutive_wins: number;
    /**
     * Max Consecutive Losses
     *
     * Length of the longest consecutive losing streak.
     */
    max_consecutive_losses: number;
    /**
     * Avg Trade Duration Seconds
     *
     * Average duration of a trade from open to close in seconds. Null when no trade has both opened_at and closed_at set.
     */
    avg_trade_duration_seconds: number | null;
    /**
     * Sharpe Ratio
     *
     * Annualised Sharpe ratio assuming a risk-free rate of zero, computed from daily PnL grouped by closed_at date. Null when fewer than 2 closed trades are available.
     */
    sharpe_ratio: string | null;
};

